code='''def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    counts = {}
    for row in g:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    # The two endpoint bars are same-color runs on opposite borders.
    edge_color = max((v for v in counts if v != bg), key=lambda v: counts[v])
    marks = [(r, c) for r in range(h) for c in range(w) if g[r][c] not in (bg, edge_color)]
    if not marks:
        return g
    ink = g[marks[0][0]][marks[0][1]]
    # Find paired runs on opposite left/right or top/bottom borders.
    vertical = (sum(g[r][0] == edge_color for r in range(h)) > 0 and
                sum(g[r][-1] == edge_color for r in range(h)) > 0)
    if vertical:
        left = [r for r in range(h) if g[r][0] == edge_color]
        right = [r for r in range(h) if g[r][-1] == edge_color]
        # Each marker selects its offset in the bar on its side; draw a full
        # corresponding line from the opposite bar, and a partial line to marker.
        for r, c in marks:
            if r in left:
                offset = r - min(left)
                counterpart = min(right) + offset
                if counterpart in right:
                    for x in range(1, w-1):
                        if g[counterpart][x] == bg: g[counterpart][x] = ink
                    for x in range(c+1, w-1):
                        if g[r][x] == bg: g[r][x] = ink
                    g[r][c] = 4
            elif r in right:
                offset = r - min(right)
                counterpart = min(left) + offset
                if counterpart in left:
                    for x in range(1, w-1):
                        if g[counterpart][x] == bg: g[counterpart][x] = ink
                    for x in range(1, c):
                        if g[r][x] == bg: g[r][x] = ink
                    g[r][c] = 4
    else:
        top = [c for c in range(w) if g[0][c] == edge_color]
        bottom = [c for c in range(w) if g[-1][c] == edge_color]
        for r, c in marks:
            if c in top:
                offset = c - min(top)
                counterpart = min(bottom) + offset
                if counterpart in bottom:
                    for y in range(1, h-1):
                        if g[y][counterpart] == bg: g[y][counterpart] = ink
                    for y in range(r+1, h-1):
                        if g[y][c] == bg: g[y][c] = ink
                    g[r][c] = 4
            elif c in bottom:
                offset = c - min(bottom)
                counterpart = min(top) + offset
                if counterpart in top:
                    for y in range(1, h-1):
                        if g[y][counterpart] == bg: g[y][counterpart] = ink
                    for y in range(1, r):
                        if g[y][c] == bg: g[y][c] = ink
                    g[r][c] = 4
    return g
'''
